// Lookup order by order_id or customer_email
const email = $('Normalize Input').first().json.email;
let classification = {};
try {
  const responseText = $('LLM Classifier & Extractor').first().json.text || '{}';
  const cleaned = responseText.replace(/```json/g, '').replace(/```/g, '').trim();
  classification = JSON.parse(cleaned);
} catch (e) {
  classification = {
    intent: 'other',
    secondary_intent: null,
    order_id: null,
    sentiment: 'neutral',
    language: 'en',
    confidence: 0.3,
    summary: 'Failed to parse JSON classification'
  };
}

const allOrders = $input.first().json.orders || [];
let matchedOrder = null;

if (classification.order_id) {
  matchedOrder = allOrders.find(o => o.order_id === classification.order_id);
}
if (!matchedOrder && email.from && email.from.email) {
  matchedOrder = allOrders.find(o => (o.customer_email || '').toLowerCase() === email.from.email.toLowerCase());
}

return {
  json: {
    email,
    classification,
    order: matchedOrder,
    order_found: !!matchedOrder
  }
};

// Return Eligibility, Privacy Check & Route Logic
const item = $input.first().json;
const email = item.email;
const classification = item.classification;
const order = item.order;
const SCENARIO_DATE = '2026-11-20';
const emailDate = new Date(email.received_at ? email.received_at.split('T')[0] : SCENARIO_DATE);

let eligibility = { is_eligible: false, reason: '', days_since_delivery: null, requires_photos: false, privacy_passed: true };
let needs_human = false;
let action_taken = 'log_only';
let ticket_priority = 'Normal';
let notes = [];
let should_create_ticket = false;
let ticket_id = '';

if (classification.confidence < 0.70) {
  needs_human = true;
  notes.push('Low confidence (< 0.70)');
}

if (order) {
  const senderEmail = (email.from.email || '').toLowerCase().trim();
  const orderEmail = (order.customer_email || '').toLowerCase().trim();
  if (senderEmail !== orderEmail) {
    eligibility.privacy_passed = false;
    needs_human = true;
    notes.push('Privacy mismatch: sender email does not match order email');
  }
}

const intent = classification.intent;
if (intent === 'order_status') {
  if (!order) { needs_human = true; action_taken = 'needs_human'; notes.push('Order not found'); }
  else if (!eligibility.privacy_passed) { action_taken = 'privacy_block'; }
  else { action_taken = 'draft_reply'; }
} else if (intent === 'product_query') {
  const b = (email.body || '').toLowerCase();
  if (['cure', 'eczema', 'psoriasis', 'allergy', 'reaction', 'rash', 'pregnant'].some(w => b.includes(w))) {
    needs_human = true;
    action_taken = 'escalate_medical_query';
    notes.push('Medical or reaction query');
  } else {
    action_taken = 'draft_reply';
  }
} else if (intent === 'return_refund' || intent === 'complaint') {
  const isComplaint = intent === 'complaint';
  ticket_priority = isComplaint ? 'High' : 'Normal';
  should_create_ticket = true;
  ticket_id = `TKT-${order ? order.order_id : 'GEN'}`;
  if (order && order.delivered_date) {
    const delDate = new Date(order.delivered_date);
    const diffDays = Math.floor(Math.abs(emailDate - delDate) / (1000 * 60 * 60 * 24));
    eligibility.days_since_delivery = diffDays;
    if (isComplaint) {
      if (diffDays <= 2) { eligibility.is_eligible = true; eligibility.requires_photos = true; eligibility.reason = 'Reported within 48h'; }
      else { eligibility.is_eligible = false; needs_human = true; eligibility.reason = 'Exceeds 48h window'; }
    } else {
      if (diffDays <= 7) { eligibility.is_eligible = true; eligibility.reason = 'Within 7-day return window'; }
      else { eligibility.is_eligible = false; eligibility.reason = 'Exceeds 7-day return window'; }
    }
  } else if (!order) {
    needs_human = true;
    notes.push('Order missing for return/complaint');
  }
  action_taken = isComplaint ? 'ticket_and_draft_complaint' : 'ticket_and_draft_return';
} else {
  action_taken = 'log_only';
}

return {
  json: {
    ...item,
    eligibility,
    needs_human,
    action_taken,
    ticket_priority,
    should_create_ticket,
    ticket_id,
    notes: notes.join('; ')
  }
};

